(function(){
'use strict';
const C=window.THCore,K=window.THCreator,W=window.THWorkbench;if(!C||!K||!W||document.body.dataset.page!=='studio')return;
const $=q=>document.querySelector(q);let source=null,sourceUrl='',output=null,generation=0,loadToken=0;
function clearOutput(){output=null;$('#download-media').disabled=true;$('#media-details').textContent='';$('#media-canvas').hidden=true;$('#media-placeholder').hidden=false;}
$('#media-file').addEventListener('change',async e=>{generation++;const load=++loadToken;clearOutput();source=null;if(sourceUrl)URL.revokeObjectURL(sourceUrl);const file=e.target.files[0];if(!file)return;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>15*1024*1024)throw Error('Chọn PNG, JPEG hoặc WebP tối đa 15 MB.');const bytes=new Uint8Array(await file.slice(0,16).arrayBuffer());const png=bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71&&bytes[4]===13&&bytes[5]===10&&bytes[6]===26&&bytes[7]===10,jpeg=bytes[0]===255&&bytes[1]===216&&bytes[2]===255,webp=String.fromCharCode(...bytes.slice(0,4))==='RIFF'&&String.fromCharCode(...bytes.slice(8,12))==='WEBP';if(!(file.type==='image/png'&&png||file.type==='image/jpeg'&&jpeg||file.type==='image/webp'&&webp))throw Error('Tệp chưa có chữ ký ảnh đúng định dạng.');sourceUrl=URL.createObjectURL(file);const image=new Image();image.decoding='async';await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('Trình duyệt không giải mã được ảnh.'));image.src=sourceUrl;});if(load!==loadToken)return;if(image.naturalWidth*image.naturalHeight>40000000)throw Error('Ảnh quá lớn để xử lý ở đây. Chọn ảnh tối đa 40 megapixel.');source={image,file};$('#media-status').textContent='Đã mở '+image.naturalWidth+' × '+image.naturalHeight+' px. Chọn khung rồi tạo ảnh.';}catch(err){if(load===loadToken)$('#media-status').textContent=err.message;}});
for(const id of ['media-ratio','media-width','media-type','media-quality'])$('#'+id).addEventListener('input',()=>{generation++;clearOutput();if(source)$('#media-status').textContent='Thông số đã đổi. Nhấn Tạo ảnh xem trước để cập nhật.';});$('#media-quality').addEventListener('input',()=>$('#media-quality-value').textContent=$('#media-quality').value+'%');
$('#media-form').addEventListener('submit',async e=>{e.preventDefault();if(!source){$('#media-status').textContent='Chọn ảnh gốc trước khi tạo.';return;}const version=++generation;clearOutput();try{const g=K.cropGeometry(source.image.naturalWidth,source.image.naturalHeight,Number($('#media-ratio').value),Number($('#media-width').value)),canvas=$('#media-canvas');canvas.width=g.width;canvas.height=g.height;const ctx=canvas.getContext('2d');if(!ctx)throw Error('Thiết bị chưa hỗ trợ xử lý ảnh Canvas.');if($('#media-type').value==='image/jpeg'){ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);}ctx.drawImage(source.image,g.sx,g.sy,g.sw,g.sh,0,0,g.width,g.height);const requested=$('#media-type').value,blob=await new Promise(resolve=>canvas.toBlob(resolve,requested,Number($('#media-quality').value)/100));if(version!==generation)return;if(!blob)throw Error('Trình duyệt chưa tạo được ảnh. Thử giảm chiều rộng.');output=blob;canvas.hidden=false;$('#media-placeholder').hidden=true;$('#download-media').disabled=false;const type=blob.type.split('/')[1]||'png';$('#media-details').textContent=g.width+' × '+g.height+' px · '+type.toUpperCase()+' · '+(blob.size/1000).toLocaleString('vi-VN',{maximumFractionDigits:1})+' KB'+(blob.size<source.file.size?' · giảm '+Math.round((1-blob.size/source.file.size)*100)+'% so với tệp gốc':'');$('#media-status').textContent=(blob.type!==requested?'Trình duyệt dùng '+type.toUpperCase()+' thay cho định dạng bạn chọn. ':'')+(g.width>g.sw?'Ảnh được phóng lớn; không tạo thêm chi tiết thật. ':'')+'Kiểm tra chữ và chủ thể trong bản xem trước.';}catch(err){$('#media-status').textContent=err.message;}});
$('#download-media').addEventListener('click',()=>{if(!output)return;const a=document.createElement('a');a.download='Tech_Horizon_Anh.'+(output.type==='image/jpeg'?'jpg':output.type==='image/webp'?'webp':'png');a.href=URL.createObjectURL(output);document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),15000);});
const stored=C.storage.get('th-studio-script','');if(typeof stored==='string'&&stored.length<=30000)$('#script-text').value=stored;
function scriptResult(){try{const m=K.metrics($('#script-text').value,$('#script-speed').value),target=Number($('#script-target').value);if(!Number.isFinite(target)||target<1||target>3600)throw Error('Thời lượng mục tiêu cần từ 1 đến 3.600 giây.');$('#script-duration').textContent=W.duration(m.seconds);$('#script-units').textContent=m.units.toLocaleString('vi-VN');$('#script-characters').textContent=m.characters.toLocaleString('vi-VN');const delta=m.seconds-target;$('#script-target-result').textContent=!m.units?'Nhập nội dung để so với thời lượng mục tiêu.':delta>0?'Dài hơn mục tiêu khoảng '+W.duration(delta)+'.':delta<0?'Ngắn hơn mục tiêu khoảng '+W.duration(-delta)+'.':'Khớp thời lượng mục tiêu theo tốc độ đã chọn.';$('#script-status').textContent='Kết quả là ước tính; ngắt nghỉ và nhấn giọng làm thay đổi thời lượng.';}catch(err){$('#script-status').textContent=err.message;}}
$('#script-form').addEventListener('submit',e=>{e.preventDefault();scriptResult();});$('#save-script').addEventListener('click',()=>$('#script-status').textContent=C.storage.set('th-studio-script',$('#script-text').value)?'Đã giữ kịch bản nháp trên thiết bị này.':'Trình duyệt chưa lưu được kịch bản.');$('#download-script').addEventListener('click',()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([$('#script-text').value],{type:'text/plain;charset=utf-8'}));a.download='Tech_Horizon_Kich_Ban.txt';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),15000);});scriptResult();
})();
